1	package consensus
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"path/filepath"
8		"sort"
9		"testing"
10	)
11	
12	// 本文件钉住“决定性投票”的原子落盘回归保障。
13	//
14	// 场景：四名验证者（确认门槛为票数严格超过名单的 2/3，即 3 票）的一轮竞争中，
15	// 本地提议包含两笔不同账户的交易，竞争候选只包含其中一笔，两笔交易进入下一轮
16	// 也不会到期。竞争候选已有两票（不足以确认），第三名验证者的一票本应使其胜出，
17	// 但这一次保存节点状态失败。该投票必须整体不生效：调用返回错误且结果为空，
18	// 当前轮次、确认高度、最新确认块、候选票数与结果、本地提议、两笔交易状态以及
19	// 账户已确认序号全部保持投票前状态；磁盘上同样不能留下第三票或临时文件。
20	// 重新打开节点看到的仍是同一份操作前状态。保存恢复正常后，同一名验证者对同一
21	// 竞争候选的再次投票必须作为新票被接收、立即确认，按候选标识与交易顺序生成
22	// 确认块并进入下一轮；落选本地提议独有的交易回到排队且不推进序号。
23	// 本组测试不新增候选规则，也不改变确认门槛。
24	
25	// hexKeys 把验证者公钥转为十六进制并按字典序排列，便于与查询返回的排序结果比对。
26	func hexKeys(pubs [][]byte) []string {
27		out := make([]string, 0, len(pubs))
28		for _, p := range pubs {
29			out = append(out, fmt.Sprintf("%x", p))
30		}
31		sort.Strings(out)
32		return out
33	}
34	
35	// assertRoundOnePending 断言节点正处于测试轮次（第 1 轮）投票前/失败后的未决状态：
36	// 轮次 1、高度 0、无确认块；本地提议标识与交易顺序不变；竞争候选保持给定票数与
37	// pending 结果、本地候选 0 票；未投票名单恰好为 unvoted；两笔交易仍在等待投票；
38	// 两个账户的已确认序号都为 0，待处理交易各一笔且说明为 waiting-vote。
39	func assertRoundOnePending(t *testing.T, n *Node, local ProposalView, altID string, altVoters, unvoted [][]byte, a1, b1 *Transaction, keys []testKey) {
40		t.Helper()
41		if n.CurrentRound() != 1 {
42			t.Fatalf("current round = %d, want 1", n.CurrentRound())
43		}
44		if n.Height() != 0 {
45			t.Fatalf("confirmed height = %d, want 0", n.Height())
46		}
47		if _, ok := n.LatestBlock(); ok {
48			t.Fatal("latest confirmed block must not exist before confirmation")
49		}
50	
51		p, ok := n.Proposal()
52		if !ok {
53			t.Fatal("local proposal must still be available")
54		}
55		if p.BlockID != local.BlockID || fmt.Sprint(p.TxIDs) != fmt.Sprint(local.TxIDs) {
56			t.Fatalf("local proposal changed: id=%s txs=%v, want id=%s txs=%v",
57				p.BlockID, p.TxIDs, local.BlockID, local.TxIDs)
58		}
59	
60		rc, err := n.Candidates(1)
61		if err != nil {
62			t.Fatal(err)
63		}
64		if rc.Ended || rc.UnconfirmedEnd || !rc.HasRecords {
65			t.Fatalf("round 1 must stay pending with records: %+v", rc)
66		}
67		if len(rc.Candidates) != 2 {
68			t.Fatalf("candidate count = %d, want 2 (local + competitor)", len(rc.Candidates))
69		}
70		var gotLocal, gotAlt *CandidateView
71		for i := range rc.Candidates {
72			switch rc.Candidates[i].BlockID {
73			case local.BlockID:
74				gotLocal = &rc.Candidates[i]
75			case altID:
76				gotAlt = &rc.Candidates[i]
77			}
78		}
79		if gotLocal == nil || gotAlt == nil {
80			t.Fatalf("both candidates must remain present: local=%p alt=%p views=%+v", gotLocal, gotAlt, rc.Candidates)
81		}
82		if !gotLocal.Local || gotLocal.Result != CandidatePending || len(gotLocal.Voters) != 0 {
83			t.Fatalf("local candidate must stay pending with no votes: %+v", gotLocal)
84		}
85		if fmt.Sprint(gotLocal.TxIDs) != fmt.Sprint(local.TxIDs) {
86			t.Fatalf("local candidate tx order changed: %v, want %v", gotLocal.TxIDs, local.TxIDs)
87		}
88		if gotAlt.Local || gotAlt.Result != CandidatePending {
89			t.Fatalf("competitor must stay pending: %+v", gotAlt)
90		}
91		if fmt.Sprint(gotAlt.TxIDs) != fmt.Sprint([]string{a1.ID()}) {
92			t.Fatalf("competitor tx order = %v, want [%s]", gotAlt.TxIDs, a1.ID())
93		}
94		if fmt.Sprint(hexKeys(gotAlt.Voters)) != fmt.Sprint(hexKeys(altVoters)) {
95			t.Fatalf("competitor voters = %x, want %x", gotAlt.Voters, altVoters)
96		}
97		if fmt.Sprint(hexKeys(rc.Unvoted)) != fmt.Sprint(hexKeys(unvoted)) {
98			t.Fatalf("unvoted validators = %x, want %x", rc.Unvoted, unvoted)
99		}
100	
101		// 两笔交易都不能提前确认，也不能回到排队：仍被未决候选引用、等待投票。
102		for _, tx := range []*Transaction{a1, b1} {
103			info := n.mustTx(t, tx.ID())
104			if info.Status != StatusProposed {
105				t.Fatalf("tx %s status = %s, want proposed (waiting for votes)", tx.ID(), info.Status)
106			}
107			if info.BlockHeight != 0 || info.BlockID != "" {
108				t.Fatalf("tx %s must not reference a confirmed block: height=%d block=%q", tx.ID(), info.BlockHeight, info.BlockID)
109			}
110		}
111		assertAccountQueue(t, n, keys[0].pub, 0, map[string]string{a1.ID(): "waiting-vote"})
112		assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{b1.ID(): "waiting-vote"})
113		if a := n.Account(keys[0].pub); a.Gap != 0 {
114			t.Fatalf("a1 account gap = %d, want 0", a.Gap)
115		}
116		if a := n.Account(keys[1].pub); a.Gap != 0 {
117			t.Fatalf("b1 account gap = %d, want 0", a.Gap)
118		}
119	}
120	
121	// TestDecisiveVoteSaveFailureAtomic 覆盖决定性投票保存失败的完整回归序列：
122	// 失败整体回滚 -> 内存/磁盘/重开三处一致 -> 恢复后再次投票作为新票确认。
123	func TestDecisiveVoteSaveFailureAtomic(t *testing.T) {
124		keys := genKeys(t, 4)
125		n, dir := newTestNode(t, keys, 10)
126	
127		// 两笔不同账户的交易，到期轮次足够大：进入第 2 轮也不会失效。
128		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
129		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 5, 100)
130		if _, err := n.Submit(a1); err != nil {
131			t.Fatal(err)
132		}
133		if _, err := n.Submit(b1); err != nil {
134			t.Fatal(err)
135		}
136		// 费用 b1(5) 高于 a1(1)：本地提议顺序固定为 b1、a1，两笔都在提议中。
137		local, err := n.Propose()
138		if err != nil {
139			t.Fatal(err)
140		}
141		if fmt.Sprint(local.TxIDs) != fmt.Sprint([]string{b1.ID(), a1.ID()}) {
142			t.Fatalf("setup: local proposal = %v, want [b1 a1]", local.TxIDs)
143		}
144		// 竞争候选只含 a1，标识与交易顺序都不同于本地提议。
145		alt, err := n.RegisterCandidate(1, []string{a1.ID()})
146		if err != nil {
147			t.Fatal(err)
148		}
149		if alt.BlockID == local.BlockID {
150			t.Fatal("setup: competitor block id must differ from local proposal")
151		}
152	
153		// 两名验证者投给竞争候选：两票未达严格超过 2/3 的门槛，不能确认。
154		firstVoters := [][]byte{keys[0].pub, keys[1].pub}
155		for i, v := range firstVoters {
156			res, err := n.Vote(v, 1, alt.BlockID)
157			if err != nil || !res.Counted || res.Confirmed {
158				t.Fatalf("competitor vote %d: %+v %v", i+1, res, err)
159			}
160		}
161		decisive := keys[2].pub
162		stillUnvoted := [][]byte{keys[2].pub, keys[3].pub}
163		assertRoundOnePending(t, n, local, alt.BlockID, firstVoters, stillUnvoted, a1, b1, keys)
164	
165		// 记录决定性投票前的磁盘文件：后续失败的保存不得改动它。
166		statePath := filepath.Join(dir, stateFileName)
167		before, err := os.ReadFile(statePath)
168		if err != nil {
169			t.Fatal(err)
170		}
171	
172		// 第三名验证者本应使竞争候选胜出，但此刻保存节点状态失败。
173		n.injectSaveErr = errors.New("disk full (simulated)")
174		res, err := n.Vote(decisive, 1, alt.BlockID)
175		n.injectSaveErr = nil
176		if err == nil {
177			t.Fatal("decisive vote must return an error when saving node state fails")
178		}
179		if reason(err) != "" {
180			t.Fatalf("save failure must surface as an infrastructure error, not a vote rejection %q: %v", reason(err), err)
181		}
182		if res != nil {
183			t.Fatalf("vote result must be nil on save failure, got %+v", res)
184		}
185	
186		// 内存：轮次、高度、最新块、候选票数/结果、未投票者、提议、交易与账户全部照旧。
187		assertRoundOnePending(t, n, local, alt.BlockID, firstVoters, stillUnvoted, a1, b1, keys)
188	
189		// 磁盘：状态文件逐字节保持投票前内容，且不残留临时文件。
190		after, err := os.ReadFile(statePath)
191		if err != nil {
192			t.Fatal(err)
193		}
194		if string(after) != string(before) {
195			t.Fatal("state file changed despite the failed save")
196		}
197		entries, err := os.ReadDir(dir)
198		if err != nil {
199			t.Fatal(err)
200		}
201		var names []string
202		for _, e := range entries {
203			names = append(names, e.Name())
204		}
205		if fmt.Sprint(names) != "[state.json]" {
206			t.Fatalf("failed save must not leave temp files, dir contains %v", names)
207		}
208	
209		// 重开节点：看到同样的操作前状态——不多出确认块，也没有只落在内存或
210		// 只落在保存记录里的第三票。
211		reopened, err := Open(dir)
212		if err != nil {
213			t.Fatal(err)
214		}
215		assertRoundOnePending(t, reopened, local, alt.BlockID, firstVoters, stillUnvoted, a1, b1, keys)
216	
217		// 保存恢复正常后，同一名验证者再次投给同一竞争候选：
218		// 必须作为新票（Counted）被接收并立即确认，而非被当成重复投票去重。
219		res, err = reopened.Vote(decisive, 1, alt.BlockID)
220		if err != nil {
221			t.Fatalf("decisive vote after recovery: %v", err)
222		}
223		if !res.Counted {
224			t.Fatal("the repeated vote must count as a new vote, not dedup as an earlier failed one")
225		}
226		if !res.Confirmed || res.Block == nil {
227			t.Fatalf("competitor must confirm immediately on the third durable vote: %+v", res)
228		}
229		if res.Block.ID != alt.BlockID || fmt.Sprint(res.Block.TxIDs) != fmt.Sprint([]string{a1.ID()}) {
230			t.Fatalf("returned block must match competitor id and tx order: %+v", res.Block)
231		}
232		if res.Block.Height != 1 || res.Block.Round != 1 || res.Block.PreviousID != "" {
233			t.Fatalf("returned block header wrong: %+v", res.Block)
234		}
235	
236		// 节点进入下一轮，确认高度推进，最新块即竞争候选块。
237		if reopened.CurrentRound() != 2 || reopened.Height() != 1 {
238			t.Fatalf("round=%d height=%d after confirmation, want 2/1", reopened.CurrentRound(), reopened.Height())
239		}
240		blk, err := reopened.BlockAt(1)
241		if err != nil {
242			t.Fatal(err)
243		}
244		if blk.ID != alt.BlockID || blk.Round != 1 || blk.Height != 1 || blk.PreviousID != "" ||
245			fmt.Sprint(blk.TxIDs) != fmt.Sprint([]string{a1.ID()}) {
246			t.Fatalf("confirmed block header/order wrong: %+v", blk)
247		}
248		if latest, ok := reopened.LatestBlock(); !ok || latest.ID != alt.BlockID {
249			t.Fatalf("latest block = %+v ok=%v, want competitor block", latest, ok)
250		}
251	
252		// 竞争候选中的交易关联确认块，所属账户已确认序号推进到 1。
253		winInfo := reopened.mustTx(t, a1.ID())
254		if winInfo.Status != StatusConfirmed || winInfo.BlockID != alt.BlockID || winInfo.BlockHeight != 1 {
255			t.Fatalf("winner tx wrong: %+v", winInfo)
256		}
257		if a := reopened.Account(keys[0].pub); a.ConfirmedSequence != 1 || len(a.Pending) != 0 {
258			t.Fatalf("winner account wrong after confirmation: %+v", a)
259		}
260		// 本地提议独有的落选交易回到排队，账户序号不因落选改变；进入第 2 轮未到期。
261		loseInfo := reopened.mustTx(t, b1.ID())
262		if loseInfo.Status != StatusQueued {
263			t.Fatalf("loser-only tx status = %s, want queued", loseInfo.Status)
264		}
265		if loseInfo.BlockHeight != 0 || loseInfo.BlockID != "" {
266			t.Fatalf("loser-only tx must not reference a block: %+v", loseInfo)
267		}
268		assertAccountQueue(t, reopened, keys[1].pub, 0, map[string]string{b1.ID(): "waiting-pack"})
269	
270		// 旧轮记录：竞争候选胜出、本地提议落选，三票完整保留，第四名仍未投票。
271		rc, err := reopened.Candidates(1)
272		if err != nil {
273			t.Fatal(err)
274		}
275		if !rc.Ended || rc.UnconfirmedEnd || !rc.HasRecords {
276			t.Fatalf("round 1 must be a confirmed, recorded round: %+v", rc)
277		}
278		for _, c := range rc.Candidates {
279			want := CandidateLost
280			if c.BlockID == alt.BlockID {
281				want = CandidateWon
282				if len(c.Voters) != 3 {
283					t.Fatalf("winner must keep exactly 3 votes including the recovered decisive one, got %d", len(c.Voters))
284				}
285			}
286			if c.Result != want {
287				t.Fatalf("candidate %s result = %s, want %s", c.BlockID, c.Result, want)
288			}
289		}
290		if fmt.Sprint(hexKeys(rc.Unvoted)) != fmt.Sprint(hexKeys([][]byte{keys[3].pub})) {
291			t.Fatalf("old-round unvoted = %x, want only validator 3", rc.Unvoted)
292		}
293	
294		// 确认结果随再次落盘持久化：再次重开后状态完全一致，不存在半生效的第三票。
295		durable, err := Open(dir)
296		if err != nil {
297			t.Fatal(err)
298		}
299		if durable.CurrentRound() != 2 || durable.Height() != 1 {
300			t.Fatalf("reopened round=%d height=%d, want 2/1", durable.CurrentRound(), durable.Height())
301		}
302		if b, ok := durable.LatestBlock(); !ok || b.ID != alt.BlockID || fmt.Sprint(b.TxIDs) != fmt.Sprint([]string{a1.ID()}) {
303			t.Fatalf("durable latest block wrong: %+v ok=%v", b, ok)
304		}
305		if info := durable.mustTx(t, a1.ID()); info.Status != StatusConfirmed || info.BlockHeight != 1 {
306			t.Fatalf("durable winner tx wrong: %+v", info)
307		}
308		if info := durable.mustTx(t, b1.ID()); info.Status != StatusQueued {
309			t.Fatalf("durable loser tx wrong: %+v", info)
310		}
311	}
