13	type testKey struct {
14		priv ed25519.PrivateKey
15		pub  ed25519.PublicKey
16	}
17	
18	func genKeys(t *testing.T, n int) []testKey {
19		t.Helper()
20		keys := make([]testKey, n)
21		for i := range keys {
22			pub, priv, err := ed25519.GenerateKey(rand.Reader)
23			if err != nil {
24				t.Fatal(err)
25			}
26			keys[i] = testKey{priv: priv, pub: pub}
27		}
28		return keys
29	}
30	
31	func newTestNode(t *testing.T, keys []testKey, maxTxs uint64) (*Node, string) {
32		t.Helper()
33		dir := t.TempDir()
34		vals := make([][]byte, len(keys))
35		for i, k := range keys {
36			vals[i] = k.pub
37		}
38		n, err := New(dir, Config{Seed: []byte("test-seed-v1"), Validators: vals, MaxTxsPerBlock: maxTxs})
39		if err != nil {
40			t.Fatal(err)
41		}
42		return n, dir
43	}
44	
45	func reason(err error) string {
46		var re *RejectError
47		if errors.As(err, &re) {
48			return re.Reason
49		}
50		return ""
51	}
52	
53	// 初始状态：轮次 1，账户确认序号 0，配置必须校验。
54	func TestInitialState(t *testing.T) {
55		keys := genKeys(t, 4)
56		n, _ := newTestNode(t, keys, 10)
57		if n.CurrentRound() != 1 {
58			t.Fatalf("initial round = %d, want 1", n.CurrentRound())
59		}
60		if n.Height() != 0 {
61			t.Fatalf("initial height = %d, want 0", n.Height())
62		}
63		acct := n.Account(keys[0].pub)
64		if acct.ConfirmedSequence != 0 {
65			t.Fatalf("initial confirmed seq = %d, want 0", acct.ConfirmedSequence)
66		}
67		if acct.Gap != 0 || len(acct.Pending) != 0 {
68			t.Fatalf("unexpected pending: %+v", acct)
69		}
70	
71		dir := t.TempDir()
72		cfg := Config{Seed: []byte("s"), Validators: [][]byte{keys[0].pub}, MaxTxsPerBlock: 1}
73		if _, err := New(dir, Config{Validators: cfg.Validators, MaxTxsPerBlock: 1}); err == nil {
74			t.Fatal("empty seed should be rejected")
75		}
76		if _, err := New(t.TempDir(), Config{Seed: []byte("s"), MaxTxsPerBlock: 1}); err == nil {
77			t.Fatal("empty validators should be rejected")
78		}
79		if _, err := New(t.TempDir(), Config{Seed: []byte("s"), Validators: cfg.Validators, MaxTxsPerBlock: 0}); err == nil {
80			t.Fatal("zero max txs should be rejected")
81		}
82		if _, err := New(t.TempDir(), Config{Seed: []byte("s"), Validators: [][]byte{keys[0].pub, keys[0].pub}, MaxTxsPerBlock: 1}); err == nil {
83			t.Fatal("duplicate validators should be rejected")
84		}
85	}
86	
87	// 签名编码与交易标识稳定。
88	func TestStableEncoding(t *testing.T) {
89		keys := genKeys(t, 1)
90		tx := NewTransaction(keys[0].priv, 7, []byte("hello"), 3, 99)
91		id1, sb1 := tx.ID(), tx.SigningBytes()
92		// 重新逐字节构造一份相同内容的交易，标识与签名编码必须一致。
93		tx2 := NewTransaction(keys[0].priv, 7, []byte("hello"), 3, 99)
94		if tx2.ID() != id1 {
95			t.Fatal("same bytes must yield same id")
96		}
97		if string(tx2.SigningBytes()) != string(sb1) {
98			t.Fatal("signing bytes must be stable")
99		}
100		if !tx2.Verify() {
