43	// 跨账户打包：后续序号必须等前一笔选入后才参与竞争，选入后凭费用进入比较。
44	// 账户甲序号 1、2 费用 30、100，账户乙序号 1、2 费用 50、20，上限 4 时
45	// 完整顺序为 乙1、甲1、甲2、乙2：甲2 开始不能越过甲1，甲1 入选后甲2 凭高费用排在乙2 前。
46	func TestProposeOrderUnlocksNextSequence(t *testing.T) {
47		keys := genKeys(t, 4)
48		n, _ := newTestNode(t, keys, 4)
49	
50		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 30, 100)
51		a2 := NewTransaction(keys[0].priv, 2, []byte("a2"), 100, 100)
52		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 50, 100)
53		b2 := NewTransaction(keys[1].priv, 2, []byte("b2"), 20, 100)
54		for _, tx := range []*Transaction{a1, a2, b1, b2} {
55			if _, err := n.Submit(tx); err != nil {
